const Telegraf = require('telegraf');
const { subMinutes } = require('date-fns'); // Para calcular datas passadas

// Crie o bot (substitua pelo seu Token e ID do @username)
const bot = new Telegraf(process.env.BOT_TOKEN || 'SEU_TOKEN_AQUI');

// Função auxiliar para formatar o tempo restante em texto legível
function formatTimeRemaining(minutesLeft) {
  if (minutesLeft <= 0) return "⏰ Tempo acabou!";

  const hours = Math.floor(minutesLeft / 60);
  const mins = Math.round(minutesLeft % 60);

  if (hours > 0) {
    return `${hours}h ${mins}m restantes`;
  } else {
    return `${mins}m restantes`;
  }
}

// --- Lógica do Bot ---

bot.start((ctx) => {
  ctx.reply(
    '👋 Olá! Eu sou seu contador regressivo.\n\n' +
    'Para começar, digite o tempo desejado no formato **HH:MM**.\n' +
    'Exemplo: 01:30 (1 hora e 30 minutos)'
  );
});

