bot.command('timer', async (ctx) => {
  try {
    const text = ctx.message.text;

    // Regex para validar formato HH:MM (ex: 01:30, 2:00, 12:59)
    const timeRegex = /^(\d{1,2}):(\d{2})$/;
    const match = text.match(timeRegex);

    if (!match) {
      return ctx.reply('❌ Formato inválido! Por favor, use o formato **HH:MM** (ex: 01:30).');
    }

    const [_, hStr, mStr] = match;
    const totalMinutes = parseInt(hStr) * 60 + parseInt(mStr);

    if (totalMinutes < 1) {
      return ctx.reply('⚠️ O tempo deve ser maior que 0.');
    }

    // --- Iniciar Contagem Regressiva ---

    let remainingTime = totalMinutes;
    let countdownInterval = null;

