      const now = new Date();
      const secondsUntilNext = Math.ceil((nextIntervalDate - now) / 1000);

      // Se ainda não chegou no momento exato, espera e avisa
      if (secondsUntilNext > 0) {
        await new Promise(resolve => setTimeout(resolve, secondsUntilNext * 1000));

        remainingTime -= 30; // Reduzimos o tempo restante

        // Ajuste fino se sobrar menos de 30 minutos
        if (remainingTime < 0) remainingTime = 0;

