                <button id="modal-action-btn" class="px-4 py-2 text-sm font-medium bg-brand-600 hover:bg-brand-500 text-white rounded-lg transition shadow-lg shadow-brand-500/20">Salvar</button>
            </div>
        </div>
    </div>

    <!-- TOAST NOTIFICATIONS -->
    <div id="toast-container"></div>

    <!-- JAVASCRIPT LOGIC -->
    <script>
        /**
         * MISSY SYSTEM CORE
         * Lógica centralizada para gerenciamento de estado, views e ações.
         */
        const app = (() => {
            // --- ESTADO DA APLICAÇÃO ---
            let state = {
                view: 'dashboard',
                clients: JSON.parse(localStorage.getItem('missy_clients')) || [],
                processes: JSON.parse(localStorage.getItem('missy_processes')) || [],
                documents: JSON.parse(localStorage.getItem('missy_documents')) || [],
                agenda: JSON.parse(localStorage.getItem('missy_agenda')) || [],
                tasks: JSON.parse(localStorage.getItem('missy_tasks')) || [],
                finance: JSON.parse(localStorage.getItem('missy_finance')) || [],
                collaborators: JSON.parse(localStorage.getItem('missy_collabs')) || [],
                intimations: JSON.parse(localStorage.getItem('missy_intimations')) || [],
                settings: JSON.parse(localStorage.getItem('missy_settings')) || {
                    officeName: "Escritório Missy",
                    lawyerName: "Dr. Carlos Silva"
                },
                notifications: []
            };

            // --- INICIALIZAÇÃO ---
            function init() {
                applySettings();
                renderSidebar();
                loadView('dashboard');

                // Listener para fechar modais ao clicar fora
                document.getElementById('modal-overlay').addEventListener('click', (e) => {
                    if (e.target.id === 'modal-overlay') app.closeModal();
                });
            }

            // --- PERSISTÊNCIA ---
            function saveState() {
                localStorage.setItem('missy_clients', JSON.stringify(state.clients));
                localStorage.setItem('missy_processes', JSON.stringify(state.processes));
                localStorage.setItem('missy_documents', JSON.stringify(state.documents));
                localStorage.setItem('missy_agenda', JSON.stringify(state.agenda));
                localStorage.setItem('missy_tasks', JSON.stringify(state.tasks));
                localStorage.setItem('missy_finance', JSON.stringify(state.finance));
                localStorage.setItem('missy_collabs', JSON.stringify(state.collaborators));
                localStorage.setItem('missy_intimations', JSON.stringify(state.intimations));
                localStorage.setItem('missy_settings', JSON.stringify(state.settings));
            }

            function showToast(message, type = 'success') {
                const container = document.getElementById('toast-container');
                const toast = document.createElement('div');
                const colors = type === 'error' ? 'bg-red-600' : 'bg-green-600';

                toast.className = `${colors} text-white px-4 py-3 rounded shadow-lg flex items-center gap-3 min-w-[300px]`;
                toast.innerHTML = `<i class="fa-solid ${type === 'error' ? 'fa-circle-exclamation' : 'fa-check-circle'}"></i> ${message}`;

                container.appendChild(toast);
                setTimeout(() => {
                    toast.style.opacity = '0';
                    toast.style.transform = 'translateX(100%)';
                    setTimeout(() => toast.remove(), 300);
                }, 3000);
            }

            // --- NAVEGAÇÃO E RENDERIZAÇÃO ---
            function navigate(viewName) {
                state.view = viewName;
                updateActiveNav(viewName);
                document.getElementById('page-title').innerText = getSectionTitle(viewName);
                loadView(viewName);
            }

            function getSectionTitle(name) {
                const titles = {
                    dashboard: 'Visão Geral', clientes: 'Clientes', processos: 'Processos', documentos: 'Documentação',
                    agenda: 'Agenda & Prazos', tarefas: 'Tarefas Pendentes', financeiro: 'Contas a Pagar',
                    colaboradores: 'Colaboradores', intimacoes: 'Intimações', backup: 'Backup & Dados', configuracoes: 'Configurações'
                };
                return titles[name] || 'Módulo';
            }

            function updateActiveNav(name) {
                document.querySelectorAll('.nav-item').forEach(el => el.classList.remove('active'));
                // Simples match baseado no onclick ou nome da função
                const map = {
                    'dashboard': 'nav-dashboard',
                    'clientes': 'nav-clientes',
                    'processos': 'nav-processos',
                    'documentos': 'nav-documentos',
                    'agenda': 'nav-agenda',
                    'tarefas': 'nav-tarefas',
                    'financeiro': 'nav-financeiro',
                    'colaboradores': 'nav-colaboradores',
                    'intimacoes': 'nav-intimacoes',
                    'backup': 'nav-backup',
                    'configuracoes': 'nav-configuracoes'
                };
                const el = document.querySelector(`[onclick="app.navigate('${map[name]}')"]`);
                if(el) el.classList.add('active');
            }

            function loadView(viewName) {
                const container = document.getElementById('content-area');
                container.innerHTML = '';
                container.classList.remove('fade-in');
                void container.offsetWidth; // Trigger reflow
                container.classList.add('fade-in');

                switch(viewName) {
                    case 'dashboard': renderDashboard(container); break;
                    case 'clientes': renderClients(container); break;
                    case 'processos': renderProcesses(container); break;
                    case 'documentos': renderDocuments(container); break;
                    case 'agenda': renderAgenda(container); break;
                    case 'tarefas': renderTasks(container); break;
                    case 'financeiro': renderFinance(container); break;
                    case 'colaboradores': renderCollaborators(container); break;
                    case 'intimacoes': renderIntimations(container); break;
                    case 'backup': renderBackup(container); break;
                    case 'configuracoes': renderConfigurations(container); break;
                }
            }

            // --- VIEWS ---

            // 1. DASHBOARD
            function renderDashboard(container) {
                const stats = [
                    { label: 'Total Clientes', value: state.clients.length, icon: 'fa-users', color: 'text-blue-400' },
                    { label: 'Processos Ativos', value: state.processes.filter(p => !p.archived).length, icon: 'fa-gavel', color: 'text-yellow-400' },
                    { label: 'Prazos Hoje', value: state.agenda.filter(a => new Date(a.date).toDateString() === new Date().toDateString()).length, icon: 'fa-clock', color: 'text-red-400' },
                    { label: 'Faturamento Mês', value: state.finance.reduce((acc, curr) => acc + (curr.type === 'entrada' ? curr.amount : 0), 0), icon: 'fa-coins', color: 'text-green-400' },
                ];

                let html = `
                    <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                        ${stats.map(s => `
                            <div class="bg-dark-card p-6 rounded-xl border border-dark-border shadow-lg hover:border-brand-500/50 transition group">
                                <div class="flex justify-between items-start">
                                    <div>
                                        <p class="text-slate-400 text-sm font-medium">${s.label}</p>
                                        <h3 class="text-3xl font-bold text-white mt-2">${s.value}</h3>
                                    </div>
                                    <div class="p-3 bg-slate-700/50 rounded-lg group-hover:bg-brand-600/20 transition">
                                        <i class="fa-solid ${s.icon} ${s.color} text-xl"></i>
                                    </div>
                                </div>
                            </div>
                        `).join('')}
                    </div>

                    <div class="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        <!-- Últimos Processos -->
                        <div class="bg-dark-card p-6 rounded-xl border border-dark-border shadow-lg">
                            <h3 class="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                                <i class="fa-solid fa-folder-open text-brand-500"></i> Processos Recentes
                            </h3>
                            <div class="overflow-x-auto">
                                <table class="w-full text-sm text-left">
                                    <thead class="text-xs text-slate-400 uppercase bg-slate-800/50">
                                        <tr><th class="px-4 py-3">Assunto</th><th class="px-4 py-3">Cliente</th><th class="px-4 py-3">Status</th></tr>
                                    </thead>
                                    <tbody>
                                        ${state.processes.slice(0, 5).map(p => `
                                            <tr class="border-b border-slate-700 hover:bg-slate-700/30">
                                                <td class="px-4 py-3 font-medium text-white truncate max-w-[150px]" title="${p.title}">${p.title}</td>
                                                <td class="px-4 py-3 text-slate-300">${p.clientName || 'Desconhecido'}</td>
                                                <td class="px-4 py-3"><span class="badge-${p.status} px-2 py-1 rounded text-xs">${p.status}</span></td>
                                            </tr>
                                        `).join('')}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        <!-- Próximos Prazos -->
                        <div class="bg-dark-card p-6 rounded-xl border border-dark-border shadow-lg">
                            <h3 class="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                                <i class="fa-solid fa-calendar-day text-brand-500"></i> Próximos Compromissos
                            </h3>
                            <ul class="space-y-3">
                                ${state.agenda.slice(0, 5).sort((a,b) => new Date(a.date) - new Date(b.date)).map(item => `
                                    <li class="flex items-center justify-between p-3 bg-slate-800/50 rounded-lg border border-slate-700">
                                        <div class="flex items-center gap-3">
                                            <div class="w-10 h-10 rounded-full bg-brand-900/50 flex items-center justify-center text-brand-500">
                                                <i class="fa-solid ${item.type === 'audiencia' ? 'fa-user' : 'fa-file'}"></i>
                                            </div>
                                            <div>
                                                <p class="text-sm font-medium text-white">${item.title}</p>
                                                <p class="text-xs text-slate-400">${new Date(item.date).toLocaleDateString()}</p>
                                            </div>
                                        </div>
                                        <span class="text-xs font-mono text-slate-500">${item.time}</span>
                                    </li>
                                `).join('')}
                                ${state.agenda.length === 0 ? '<li class="text-slate-500 italic text-center py-4">Nenhum compromisso agendado.</li>' : ''}
                            </ul>
                        </div>
                    </div>
                `;
                container.innerHTML = html;
            }

            // 2. CLIENTES
            function renderClients(container) {
                let html = `
                    <div class="flex justify-between items-center mb-6">
                        <h3 class="text-xl font-bold text-white">Gerenciar Clientes</h3>
                        <button onclick="app.openClientModal()" class="bg-brand-600 hover:bg-brand-500 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition shadow-lg shadow-brand-500/20">
                            <i class="fa-solid fa-plus"></i> Novo Cliente
                        </button>
                    </div>

                    <div class="bg-dark-card rounded-xl border border-dark-border overflow-hidden shadow-lg">
                        <table class="w-full text-left">
                            <thead class="bg-slate-800 text-slate-400 text-xs uppercase">
                                <tr><th class="px-6 py-4">Nome</th><th class="px-6 py-4">Email</th><th class="px-6 py-4">Telefone</th><th class="px-6 py-4">Processos</th><th class="px-6 py-4">Ações</th></tr>
                            </thead>
                            <tbody class="divide-y divide-slate-700">
                                ${state.clients.map(c => `
                                    <tr class="hover:bg-slate-700/30 transition">
                                        <td class="px-6 py-4 font-medium text-white flex items-center gap-3">
                                            <div class="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center text-brand-500 font-bold">${c.name.charAt(0)}</div>
                                            ${c.name}
                                        </td>
                                        <td class="px-6 py-4 text-slate-300">${c.email}</td>
                                        <td class="px-6 py-4 text-slate-300">${c.phone}</td>
                                        <td class="px-6 py-4 text-slate-400 text-sm">${state.processes.filter(p => p.clientId === c.id).length}</td>
                                        <td class="px-6 py-4">
                                            <button onclick="app.openClientEditModal(${c.id})" class="text-blue-400 hover:text-blue-300 mx-2"><i class="fa-solid fa-edit"></i></button>
                                            <button onclick="app.deleteItem('clients', ${c.id})" class="text-red-400 hover:text-red-300 mx-2"><i class="fa-solid fa-trash"></i></button>
                                        </td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                        ${state.clients.length === 0 ? '<div class="p-8 text-center text-slate-500">Nenhum cliente cadastrado.</div>' : ''}
                    </div>
                `;
                container.innerHTML = html;
            }

            // 3. PROCESSOS
            function renderProcesses(container) {
                let html = `
                    <div class="flex justify-between items-center mb-6">
                        <h3 class="text-xl font-bold text-white">Meus Processos</h3>
                        <button onclick="app.openProcessModal()" class="bg-brand-600 hover:bg-brand-500 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition shadow-lg shadow-brand-500/20">
                            <i class="fa-solid fa-plus"></i> Novo Processo
                        </button>
                    </div>
                    <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        ${state.processes.map(p => {
                            const client = state.clients.find(c => c.id == p.clientId);
                            const statusColor = p.status === 'arquivado' ? 'bg-slate-600' : p.status === 'pendente' ? 'bg-yellow-600' : 'bg-green-600';
                            return `
                            <div class="bg-dark-card rounded-xl border border-dark-border p-5 hover:border-brand-500/50 transition shadow-lg group">
                                <div class="flex justify-between items-start mb-4">
                                    <span class="text-xs font-bold uppercase tracking-wider ${statusColor} text-white px-2 py-1 rounded">${p.status}</span>
                                    <div class="opacity-0 group-hover:opacity-100 transition flex gap-2">
                                        <button onclick="app.openProcessEditModal(${p.id})" class="text-blue-400 hover:text-white"><i class="fa-solid fa-pen-to-square"></i></button>
                                        <button onclick="app.deleteItem('processes', ${p.id})" class="text-red-400 hover:text-white"><i class="fa-solid fa-trash"></i></button>
                                    </div>
                                </div>
                                <h4 class="text-lg font-semibold text-white mb-1 line-clamp-2">${p.title}</h4>
                                <p class="text-sm text-slate-400 mb-4">Assunto: ${p.subject}</p>
                                <div class="space-y-2 mb-4">
                                    <div class="flex items-center gap-2 text-xs text-slate-300">
                                        <i class="fa-solid fa-user w-4"></i> <span>${client?.name || 'Sem Cliente'}</span>
                                    </div>
                                    <div class="flex items-center gap-2 text-xs text-slate-300">
                                        <i class="fa-solid fa-gavel w-4"></i> <span>Nº: ${p.number}</span>
                                    </div>
                                </div>
                                <div class="pt-4 border-t border-slate-700 flex justify-between items-center text-xs text-slate-500">
                                    <span>${new Date(p.dateCreated).toLocaleDateString()}</span>
                                    <span class="truncate max-w-[100px]" title="${p.description}">${p.description}</span>
                                </div>
                            </div>
                        `}).join('')}
                        ${state.processes.length === 0 ? '<div class="col-span-3 text-center text-slate-500 py-10">Nenhum processo encontrado.</div>' : ''}
                    </div>
                `;
                container.innerHTML = html;
            }

            // 4. DOCUMENTOS
            function renderDocuments(container) {
                let html = `
                    <div class="flex justify-between items-center mb-6">
                        <h3 class="text-xl font-bold text-white">Documentação</h3>
                        <button onclick="app.openDocModal()" class="bg-brand-600 hover:bg-brand-500 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition shadow-lg shadow-brand-500/20">
                            <i class="fa-solid fa-upload"></i> Adicionar Arquivo
                        </button>
                    </div>
                    <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        ${state.documents.map(d => `
                            <div class="bg-dark-card rounded-xl border border-dark-border p-4 hover:shadow-lg transition group">
                                <div class="flex justify-between items-start mb-3">
                                    <i class="fa-solid fa-file-pdf text-red-500 text-3xl opacity-50 group-hover:opacity-100"></i>
                                    <button onclick="app.deleteItem('documents', ${d.id})" class="text-slate-500 hover:text-red-400"><i class="fa-solid fa-trash"></i></button>
                                </div>
                                <h4 class="text-white font-medium mb-1 truncate">${d.title}</h4>
                                <p class="text-xs text-slate-400 mb-2">Arquivo: ${d.fileType}</p>
                                <div class="flex items-center gap-2 text-xs text-brand-400 bg-brand-900/20 px-2 py-1 rounded">
                                    <i class="fa-solid fa-link"></i> Processo: ${d.processId}
                                </div>
                            </div>
                        `).join('')}
                    </div>
                `;
                container.innerHTML = html;
            }

            // 5. AGENDA
            function renderAgenda(container) {
                // Filtra por data atual ou próximos dias
                const today = new Date();
                const nextWeek = new Date(today); nextWeek.setDate(today.getDate() + 7);
                const upcoming = state.agenda.filter(a => new Date(a.date) >= today && new Date(a.date) <= nextWeek).sort((a,b) => new Date(a.date) - new Date(b.date));

                let html = `
                    <h3 class="text-xl font-bold text-white mb-6">Agenda Semanal</h3>
                    <div class="bg-dark-card rounded-xl border border-dark-border overflow-hidden shadow-lg">
                        <div class="overflow-x-auto">
                            <table class="w-full text-left border-collapse">
                                <thead class="bg-slate-800 text-slate-400 text-xs uppercase">
                                    <tr>
                                        <th class="px-4 py-3">Data/Hora</th>
                                        <th class="px-4 py-3">Tipo</th>
                                        <th class="px-4 py-3">Descrição</th>
                                        <th class="px-4 py-3">Ações</th>
                                    </tr>
                                </thead>
                                <tbody class="divide-y divide-slate-700">
                                    ${upcoming.map(item => `
                                        <tr class="hover:bg-slate-700/30">
                                            <td class="px-4 py-3 text-sm text-white font-mono">${item.date.split('T')[0]} às ${item.time}</td>
                                            <td class="px-4 py-3">
                                                <span class="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${item.type === 'audiencia' ? 'bg-purple-500/20 text-purple-400' : 'bg-blue-500/20 text-blue-400'}">
                                                    ${item.type === 'audiencia' ? 'Aud.' : 'Outro'}
                                                </span>
                                            </td>
                                            <td class="px-4 py-3 text-sm text-slate-300">${item.title}</td>
                                            <td class="px-4 py-3">
                                                <button onclick="app.openAgendaModal('${item.id}')" class="text-blue-400 hover:text-white"><i class="fa-solid fa-pen"></i></button>
                                                <button onclick="app.deleteItem('agenda', ${item.id})" class="text-red-400 hover:text-white ml-2"><i class="fa-solid fa-trash"></i></button>
                                            </td>
                                        </tr>
                                    `).join('')}
                                    ${upcoming.length === 0 ? '<tr><td colspan="4" class="px-4 py-8 text-center text-slate-500">Agenda vazia nesta semana.</td></tr>' : ''}
                                </tbody>
                            </table>
                        </div>
                    </div>
                `;
                container.innerHTML = html;
            }

            // 6. TAREFAS
            function renderTasks(container) {
                const pending = state.tasks.filter(t => !t.completed);
                const completed = state.tasks.filter(t => t.completed);

                let html = `
                    <div class="mb-6 flex gap-4">
                        <button onclick="app.renderTasks('pending')" class="pb-2 text-brand-400 border-b-2 border-brand-400 font-medium">Pendentes (${pending.length})</button>
                        <button onclick="app.renderTasks('completed')" class="pb-2 text-slate-500 hover:text-slate-300 border-b-2 border-transparent font-medium">Concluídas (${completed.length})</button>
                    </div>

                    <div class="bg-dark-card rounded-xl border border-dark-border p-6 shadow-lg min-h-[400px]">
                        <div class="flex flex-col h-full">
                            ${pending.length > 0 ? pending.map(t => `
                                <div class="flex items-start gap-4 p-3 rounded-lg hover:bg-slate-700/30 mb-3 transition">
                                    <input type="checkbox" ${t.completed ? 'checked' : ''} onchange="app.toggleTask(${t.id})" class="mt-1 w-5 h-5 rounded border-slate-600 bg-slate-700 focus:ring-brand-500 accent-brand-500 cursor-pointer">
                                    <div class="flex-1">
                                        <p class="${t.completed ? 'line-through text-slate-500' : 'text-slate-200'} text-lg">${t.text}</p>
                                        <p class="text-xs text-slate-500 mt-1">${t.deadline ? 'Vence: ' + t.deadline : ''}</p>
                                    </div>
                                    <button onclick="app.deleteItem('tasks', ${t.id})" class="text-slate-600 hover:text-red-400"><i class="fa-solid fa-trash"></i></button>
                                </div>
                            `).join('') : '<div class="text-center text-slate-500 mt-10">Nenhuma tarefa pendente.</div>'}

                            <div class="mt-auto pt-4 border-t border-slate-700">
                                <button onclick="app.openTaskModal()" class="w-full bg-slate-700 hover:bg-slate-600 text-white py-2 rounded-lg transition flex items-center justify-center gap-2">
                                    <i class="fa-solid fa-plus"></i> Nova Tarefa
                                </button>
                            </div>
                        </div>
                    </div>
                `;
                container.innerHTML = html;
            }

            // 7. FINANCEIRO
            function renderFinance(container) {
                let html = `
                    <div class="flex justify-between items-center mb-6">
                        <h3 class="text-xl font-bold text-white">Fluxo Financeiro</h3>
                        <button onclick="app.openFinanceModal()" class="bg-brand-600 hover:bg-brand-500 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition shadow-lg shadow-brand-500/20">
                            <i class="fa-solid fa-plus"></i> Lançamento
                        </button>
                    </div>

                    <div class="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
                        <div class="bg-gradient-to-br from-green-900 to-slate-800 p-6 rounded-xl border border-green-800 shadow-lg">
                            <p class="text-green-200 text-sm font-medium">Entradas</p>
                            <p class="text-2xl font-bold text-white mt-1">+ R$ ${state.finance.filter(f => f.type === 'entrada').reduce((a,b)=>a+b.amount, 0).toLocaleString('pt-BR', {minimumFractionDigits: 2})}</p>
                        </div>
                        <div class="bg-gradient-to-br from-red-900 to-slate-800 p-6 rounded-xl border border-red-800 shadow-lg">
                            <p class="text-red-200 text-sm font-medium">Saídas</p>
                            <p class="text-2xl font-bold text-white mt-1">- R$ ${state.finance.filter(f => f.type === 'saida').reduce((a,b)=>a+b.amount, 0).toLocaleString('pt-BR', {minimumFractionDigits: 2})}</p>
                        </div>
                        <div class="bg-slate-800 p-6 rounded-xl border border-slate-700 shadow-lg">
                            <p class="text-slate-400 text-sm font-medium">Saldo Total</p>
                            <p class="text-2xl font-bold text-white mt-1">R$ ${(state.finance.reduce((a,b)=>a + (b.type === 'entrada' ? b.amount : -b.amount), 0)).toLocaleString('pt-BR', {minimumFractionDigits: 2})}</p>
                        </div>
                    </div>

                    <div class="bg-dark-card rounded-xl border border-dark-border overflow-hidden shadow-lg">
                        <table class="w-full text-left">
                            <thead class="bg-slate-800 text-slate-400 text-xs uppercase">
                                <tr><th class="px-6 py-4">Data</th><th class="px-6 py-4">Descrição</th><th class="px-6 py-4">Tipo</th><th class="px-6 py-4 text-right">Valor</th></tr>
                            </thead>
                            <tbody class="divide-y divide-slate-700">
                                ${state.finance.sort((a,b) => new Date(b.date) - new Date(a.date)).slice(0, 20).map(f => `
                                    <tr class="hover:bg-slate-700/30">
