                localStorage.setItem('missy_clients', JSON.stringify(state.clients));
                localStorage.setItem('missy_processes', JSON.stringify(state.processes));
                localStorage.setItem('missy_documents', JSON.stringify(state.documents));
                localStorage.setItem('missy_agenda', JSON.stringify(state.agenda));
                localStorage.setItem('missy_tasks', JSON.stringify(state.tasks));
