                    case 'dashboard': renderDashboard(container); break;
                    case 'clientes': renderClients(container); break;
                    case 'processos': renderProcesses(container); break;
                    case 'documentos': renderDocuments(container); break;
                    case 'agenda': renderAgenda(container); break;
                    case 'tarefas': renderTasks(container); break;
                    case 'financeiro': renderFinance(container); break;
                    case 'colaboradores': renderCollaborators(container); break;
                    case 'intimacoes': renderIntimations(container); break;
