            // --- FUNÇÕES DE CRUD E UTILITÁRIAS ---

            function openClientModal() {
                document.getElementById('modal-title').innerText = 'Novo Cliente';
                document.getElementById('modal-body').innerHTML = `
                    <div class="space-y-4">
                        <input type="text" id="c-name" placeholder="Nome Completo" class="custom-input w-full p-3 rounded-lg" required>
                        <input type="email" id="c-email" placeholder="E-mail" class="custom-input w-full p-3 rounded-lg">
                        <input type="tel" id="c-phone" placeholder="Telefone" class="custom-input w-full p-3 rounded-lg">
                    </div>
                `;
                document.getElementById('modal-action-btn').onclick = () => {
                    const name = document.getElementById('c-name').value;
                    if(!name) return alert('Nome obrigatório');
                    addClient({ name, email: document.getElementById('c-email').value, phone: document.getElementById('c-phone').value });
                    closeModal();
                };
                document.getElementById('modal-overlay').classList.remove('hidden');
            }

            function openClientEditModal(id) {
                const c = state.clients.find(x => x.id === id);
                document.getElementById('modal-title').innerText = 'Editar Cliente';
                document.getElementById('modal-body').innerHTML = `
                    <div class="space-y-4">
                        <input type="text" id="c-name" value="${c.name}" class="custom-input w-full p-3 rounded-lg" required>
                        <input type="email" id="c-email" value="${c.email}" class="custom-input w-full p-3 rounded-lg">
                        <input type="tel" id="c-phone" value="${c.phone}" class="custom-input w-full p-3 rounded-lg">
                    </div>
                `;
                document.getElementById('modal-action-btn').onclick = () => {
                    addClient({ ...c, name: document.getElementById('c-name').value, email: document.getElementById('c-email').value, phone: document.getElementById('c-phone').value });
                    closeModal();
                };
                document.getElementById('modal-overlay').classList.remove('hidden');
            }

            function addClient(data) {
                state.clients.push({ ...data, id: Date.now() });
                saveState();
                showToast('Cliente cadastrado com sucesso!');
                renderClients(document.getElementById('content-area'));
            }

            function deleteItem(collection, id) {
                if(confirm('Tem certeza que deseja excluir?')) {
                    state[collection] = state[collection].filter(item => item.id !== id);
                    saveState();
                    showToast('Item excluído.', 'error');
                    renderCurrentView();
                }
            }

